export const MYTHIC_ARENA_GEOMETRY_IDENTITY_ATLAS = { src: './assets/bosses/mythic-arena-geometry-icons.png', columns: 3, rows: 2, cellSize: 96, width: 288, height: 192 };
export function mythicArenaGeometryIdentityIcon(id) { const [c, r] = CELL[id], m = META[id]; return { id, label: m.label, accent: m.accent, sx: c * 96, sy: r * 96, sw: 96, sh: 96, animated: false, motionAmplitude: 0, safeLaneIdentitySupported: true, weakpointReliefIdentityStable: true, maxVisibleIcons: 1, textFallbackPreserved: true, loadFailureBlocksGameplay: false }; }
export function auditMythicArenaGeometryIdentityAtlas() { const icons = MYTHIC_ARENA_GEOMETRY_IDENTITY_IDS.map(mythicArenaGeometryIdentityIcon); const outOfBounds = icons.filter(i => i.sx < 0 || i.sy < 0 || i.sx + i.sw > MYTHIC_ARENA_GEOMETRY_IDENTITY_ATLAS.width || i.sy + i.sh > MYTHIC_ARENA_GEOMETRY_IDENTITY_ATLAS.height).map(i => i.id); const uniqueCellCount = new Set(icons.map(i => `${i.sx}:${i.sy}`)).size; const coverage = icons.length / 6; return { coverage, uniqueCellCount, outOfBounds, passed: coverage === 1 && uniqueCellCount === 6 && outOfBounds.length === 0 }; }
